const en={nav:['Home','Map','Routes','Stories','Contribute','About'],explore:'Explore map',read:'Read the full story',more:'More stories',places:'places',hours:'hours',all:'All',search:'Search places, activities, stories or keywords',mapTitle:'One city, many ways to live green.',mapIntro:'Start with neighbourhood places and stories, then find a route of your own.',filters:['Everyday entry','Ecology tags','Area'],routesTitle:'Take another route. Meet another Macau.',routesIntro:'Follow local places and people at a slower pace.',storiesTitle:'People & place stories',storiesIntro:'See the people and you begin to see the power of place.',contributeTitle:'Recommend a good place.',contributeIntro:'Share a place, person or action you care about.',aboutTitle:'About Green GO',aboutBody:'We begin with Macau’s places, people and local action. This map helps more people notice the quiet changes already happening in everyday life. Every thoughtful choice can make the city greener and more liveable.',submit:'Submit recommendation',contact:'Contact',reason:'Why recommend it?',name:'Name',address:'Address',type:'Type',success:'Thank you. We will review your recommendation before adding it to the map.'};
const fallbackSite={heroEyebrowZh:'澳門 · 探索 · 體驗 · 人',heroEyebrowEn:'MACAU · EXPLORE · EXPERIENCE · PEOPLE',heroTitleZh:'從一個地方，\n遇見更好的日常。',heroTitleEn:'Begin with a place.\nMeet a better everyday life.',heroBodyZh:'帶入永續旅遊、融入生活、在地探索，走進更綠色、更關懷與更有韌性的日常。',heroBodyEn:'Travel slowly, live locally and discover a greener, kinder and more resilient Macau.',heroImage:'assets/macau-waterfront.png',heroArticleId:'story-afa',searchPlaceholderZh:'搜尋地點、活動、文章或關鍵字',searchPlaceholderEn:'Search places, activities, stories or keywords',hotSearchesZh:['修補日常','澳門滋味','親近自然'],hotSearchesEn:['Repair culture','Local flavours','Urban nature'],categories:[],featureEyebrowZh:'一個地方 · 一段故事',featureEyebrowEn:'ONE PLACE · ONE STORY',featureTitleZh:'阿發修鞋店',featureTitleEn:'A Fa Shoe Repair',featureBodyZh:'修補的不只是鞋，也是這座城市的溫度。',featureBodyEn:'Repair preserves more than a pair of shoes. It keeps the city’s memories close.',featureImage:'assets/shoe-repair.png',featureSideImage:'assets/macau-waterfront.png',featureArticleId:'story-afa',featureBadgeZh:'好的事，在這裡發生。',featureBadgeEn:'Good things happen here.',featureBadgeSubZh:'人 · 社區 · 自然',featureBadgeSubEn:'People · Community · Nature',storiesTitleZh:'把城市走成一段故事',storiesTitleEn:'Walk the city as a collection of stories',storiesBodyZh:'從不同角度認識澳門，發現生活中的綠意與可能。',storiesBodyEn:'Meet Macau from different angles and find greener possibilities.',storyArticleIds:['story-garden','story-afa','story-youth']};
const state={page:'home',id:'',lang:localStorage.getItem('gg-lang')==='en'?'en':'zh',places:[],articles:[],routes:[],site:fallbackSite,config:{},cat:'全部',tag:'全部',area:'全部',query:'',view:'map',menu:false};
const app=$('#app');let map;
const T=()=>state.lang==='en'?en:zh;
const loc=(item,key,englishKey=`${key}_en`)=>state.lang==='en'?(item?.[englishKey]||item?.[key]||''):(item?.[key]||'');
const S=key=>state.site[`${key}${state.lang==='en'?'En':'Zh'}`]||state.site[`${key}Zh`]||'';
const imagePath=v=>v||'assets/macau-waterfront.png';
const navKeys=['home','map','routes','stories','contribute','about'];
function logo(){return `<a class="brand" href="#home"><img src="assets/grg-logo.png" alt=""><span><strong>綠門GO</strong><small>GREEN GO · MACAU</small></span></a>`}
function header(){return `<header class="site-header"><div class="header-inner">${logo()}<button class="menu-button" data-action="menu" aria-label="Menu">${I(state.menu?'close':'menu',24)}</button><nav class="main-nav ${state.menu?'open':''}">${navKeys.map((k,i)=>`<a href="#${k}" class="${state.page===k?'active':''}">${T().nav[i]}</a>`).join('')}</nav><div class="header-tools"><button data-action="search">${I('search',21)}</button><button class="language" data-action="language">${I('globe',18)} ${state.lang==='en'?'繁':'EN'}</button></div></div></header>`}
function footer(){return `<footer class="site-footer"><div>${logo()}<p>${state.lang==='en'?'A local map for greener everyday life.':'從一個地方出發，看見更好的日常。'}</p></div><nav>${navKeys.slice(1).map((k,i)=>`<a href="#${k}">${T().nav[i+1]}</a>`).join('')}</nav><small>© 綠門GO Macau</small></footer>`}
function layout(body,{showFooter=true}={}){app.innerHTML=`${header()}${body}${showFooter?footer():''}`}
function articleFor(id){return state.articles.find(a=>a.id===id)}
function goArticle(id){return `#article/${encodeURIComponent(id||'')}`}
function home(){const categories=state.site.categories?.length?state.site.categories:[{key:'食',titleZh:'食',titleEn:'Eat',subtitleZh:'品味在地風味',subtitleEn:'Taste local flavours',image:'assets/macau-waterfront.png'},{key:'買',titleZh:'買',titleEn:'Shop',subtitleZh:'發掘特色好物',subtitleEn:'Choose thoughtful goods',image:'assets/macau-waterfront.png'},{key:'修',titleZh:'修',titleEn:'Repair',subtitleZh:'延續物件的生命',subtitleEn:'Give objects another life',image:'assets/shoe-repair.png'},{key:'去',titleZh:'去',titleEn:'Explore',subtitleZh:'探索澳門之美',subtitleEn:'Discover another Macau',image:'assets/macau-waterfront.png'},{key:'學',titleZh:'學',titleEn:'Learn',subtitleZh:'從自然與社區學習',subtitleEn:'Learn from place and nature',image:'assets/macau-waterfront.png'},{key:'參與',titleZh:'參與',titleEn:'Join',subtitleZh:'一起創造改變',subtitleEn:'Take part in local change',image:'assets/shoe-repair.png'}];const hot=state.site[state.lang==='en'?'hotSearchesEn':'hotSearchesZh']||[];const featured=articleFor(state.site.featureArticleId);const storyArticles=(state.site.storyArticleIds||[]).map(articleFor).filter(Boolean);layout(`<main class="home-page"><section class="home-hero"><div class="hero-copy"><p class="eyebrow">${esc(S('heroEyebrow'))}</p><h1>${esc(S('heroTitle')).replace(/\n/g,'<br>')}</h1><p class="hero-body">${esc(S('heroBody'))}</p><form class="editorial-search" data-search-form><span>${I('search')}</span><input name="q" placeholder="${esc(state.site[state.lang==='en'?'searchPlaceholderEn':'searchPlaceholderZh']||T().search)}"><button>${I('search',19)}</button></form><div class="hot"><span>${state.lang==='en'?'Popular:':'熱門搜尋：'}</span>${hot.map(x=>`<button data-quick="${esc(x)}">${esc(x)}</button>`).join('')}</div></div><a class="hero-visual" href="${goArticle(state.site.heroArticleId)}"><img src="${esc(imagePath(state.site.heroImage))}" alt=""><span>${state.lang==='en'?'Explore Macau':'探索澳門'} ${I('arrow')}</span></a></section><section class="category-gallery">${categories.map(c=>`<a href="#map?cat=${encodeURIComponent(c.key)}" class="category-tile"><img src="${esc(imagePath(c.image))}" alt=""><span class="category-shade"></span><span class="category-copy"><strong>${esc(state.lang==='en'?c.titleEn:c.titleZh)}</strong><small>${esc(state.lang==='en'?c.subtitleEn:c.subtitleZh)}</small></span><i>${I('arrow',16)}</i></a>`).join('')}</section><section class="home-feature"><div class="feature-photo"><img src="${esc(imagePath(state.site.featureImage))}" alt=""><div><strong>${esc(S('featureBadge'))}</strong><small>${esc(S('featureBadgeSub'))}</small></div></div><div class="feature-copy"><p class="eyebrow">${esc(S('featureEyebrow'))}</p><h2>${esc(S('featureTitle'))}</h2><p>${esc(S('featureBody'))}</p><a href="${goArticle(featured?.id||state.site.featureArticleId)}">${T().read} ${I('arrow',17)}</a></div></section><section class="home-stories"><div class="section-head"><div><h2>${esc(S('storiesTitle'))}</h2><p>${esc(S('storiesBody'))}</p></div><a href="#stories">${T().more} ${I('arrow',16)}</a></div><div class="story-strip">${storyArticles.map((a,i)=>storyHorizontal(a,i)).join('')||state.articles.slice(0,3).map((a,i)=>storyHorizontal(a,i)).join('')}</div></section></main>`)}
function storyHorizontal(a,i){return `<a class="story-horizontal" href="${goArticle(a.id)}"><span class="story-no">0${i+1}</span><span><small>${esc(loc(a,'category'))}</small><strong>${esc(loc(a,'title'))}</strong><p>${esc(loc(a,'subtitle'))}</p></span><img src="${esc(imagePath(a.img))}" alt=""><i>${I('arrow',16)}</i></a>`}
function filteredPlaces(){const q=state.query.toLowerCase();return state.places.filter(p=>(state.cat==='全部'||p.cat===state.cat)&&(state.area==='全部'||p.area===state.area)&&(state.tag==='全部'||p.tags?.includes(state.tag))&&(!q||[p.name,p.en,p.address,p.desc,...(p.tags||[])].join(' ').toLowerCase().includes(q)))}
function chip(kind,value,label=value){return `<button class="filter-chip ${state[kind]===value?'active':''}" data-filter="${kind}" data-value="${esc(value)}">${esc(label)}</button>`}
function mapPage(){const cats=['全部','食','買','修','去','學','參與'],tags=['全部','食物','減廢','水','自然與生物多樣性','社區','文化','青年'],areas=['全部','澳門半島','氹仔','路環'];const list=filteredPlaces();layout(`<main class="map-page"><section class="page-intro"><p class="eyebrow">${T().explore}</p><h1>${T().mapTitle}</h1><p>${T().mapIntro}</p></section><div class="map-shell"><aside class="map-filters"><div class="view-tabs"><button class="${state.view==='map'?'active':''}" data-view="map">${I('map')} ${T().nav[1]}</button><button class="${state.view==='list'?'active':''}" data-view="list">☷ ${state.lang==='en'?'List':'列表'}</button></div><form class="map-search" data-map-search><input name="q" value="${esc(state.query)}" placeholder="${T().search}"><button>${I('search')}</button></form>${[[cats,'cat',T().filters[0]],[tags,'tag',T().filters[1]],[areas,'area',T().filters[2]]].map(([a,k,title])=>`<div class="filter-group"><h3>${title}</h3><div>${a.map(v=>chip(k,v,v==='全部'?T().all:v)).join('')}</div></div>`).join('')}<p class="result-count">${list.length} ${T().places}</p></aside><section class="map-stage ${state.view==='list'?'list-mode':''}">${state.view==='map'?'<div id="leaflet-map"></div>':`<div class="place-list">${list.map(placeCard).join('')}</div>`}</section></div></main>`,{showFooter:false});if(state.view==='map')setTimeout(()=>initMap(list),0)}
function placeCard(p){return `<a class="place-card" href="#place/${p.id}"><img src="${esc(imagePath(p.img))}" alt=""><div><small>${esc(p.area)} · ${esc(p.cat)}</small><h3>${esc(loc(p,'name','en'))}</h3><p>${esc(loc(p,'desc','desc_en'))}</p><span>${(p.tags||[]).map(t=>`<i>${esc(t)}</i>`).join('')}</span></div>${I('arrow')}</a>`}
function initMap(list){if(map){map.remove();map=null}const el=$('#leaflet-map');if(!el||!window.L)return;map=L.map(el,{zoomControl:true}).setView([22.178,113.548],13);const key=state.config.maptilerKey;L.tileLayer(key?`https://api.maptiler.com/maps/streets-v2/{z}/{x}/{y}.png?key=${encodeURIComponent(key)}`:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:key?'© MapTiler © OpenStreetMap':'© OpenStreetMap'}).addTo(map);list.forEach(p=>L.marker([p.lat,p.lng]).addTo(map).bindPopup(`<a class="map-popup" href="#place/${p.id}"><strong>${esc(loc(p,'name','en'))}</strong><span>${esc(loc(p,'desc','desc_en'))}</span></a>`))}
function placePage(){const p=state.places.find(x=>x.id===state.id);if(!p)return notFound();layout(`<main class="detail-page"><a class="back" href="#map">← ${T().nav[1]}</a><section class="place-hero"><img src="${esc(imagePath(p.img))}" alt=""><div><p class="eyebrow">${esc(p.area)} · ${esc(p.cat)}</p><h1>${esc(loc(p,'name','en'))}</h1><p class="lead">${esc(loc(p,'desc','desc_en'))}</p><div class="tags">${(p.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div><dl><div><dt>${I('pin')}</dt><dd>${esc(loc(p,'address','address_en'))}</dd></div><div><dt>${I('clock')}</dt><dd>${esc(loc(p,'hours','hours_en'))}</dd></div>${p.phone?`<div><dt>☎</dt><dd>${esc(p.phone)}</dd></div>`:''}</dl><a class="button" href="#map">${T().explore} ${I('arrow')}</a></div></section><section class="article-body"><p class="eyebrow">${state.lang==='en'?'PLACE STORY':'地方故事'}</p><h2>${esc(loc(p,'name','en'))}</h2>${paragraphs(loc(p,'story','story_en')||loc(p,'desc','desc_en'))}</section></main>`)}
function routesPage(){layout(`<main class="listing-page"><section class="page-intro"><p class="eyebrow">${T().nav[2]}</p><h1>${T().routesTitle}</h1><p>${T().routesIntro}</p></section><div class="route-grid">${state.routes.map((r,i)=>`<a class="route-card" href="#route/${r.id}"><img src="${esc(imagePath(r.img||state.places.find(p=>r.ids?.includes(p.id))?.img))}" alt=""><div><span>0${i+1}</span><small>${esc(loc(r,'cat','cat_en'))}</small><h2>${esc(loc(r,'n','n_en'))}</h2><p>${esc(loc(r,'text','text_en'))}</p><footer>${r.ids?.length||0} ${T().places} · ${esc(loc(r,'time','time_en'))}</footer></div></a>`).join('')}</div></main>`)}
function routePage(){const r=state.routes.find(x=>x.id===state.id);if(!r)return notFound();const stops=(r.ids||[]).map(id=>state.places.find(p=>p.id===id)).filter(Boolean);layout(`<main class="detail-page"><a class="back" href="#routes">← ${T().nav[2]}</a><section class="route-detail-head"><p class="eyebrow">${esc(loc(r,'cat','cat_en'))}</p><h1>${esc(loc(r,'n','n_en'))}</h1><p>${esc(loc(r,'text','text_en'))}</p><span>${stops.length} ${T().places} · ${esc(loc(r,'time','time_en'))}</span></section><div class="route-stops">${stops.map((p,i)=>`<a href="#place/${p.id}"><b>0${i+1}</b><img src="${esc(imagePath(p.img))}" alt=""><div><small>${esc(p.area)}</small><h2>${esc(loc(p,'name','en'))}</h2><p>${esc(loc(p,'desc','desc_en'))}</p></div>${I('arrow')}</a>`).join('')}</div></main>`)}
function storiesPage(){layout(`<main class="listing-page"><section class="page-intro"><p class="eyebrow">${T().nav[3]}</p><h1>${T().storiesTitle}</h1><p>${T().storiesIntro}</p></section><div class="article-grid">${state.articles.map(a=>`<a href="${goArticle(a.id)}"><img src="${esc(imagePath(a.img))}" alt=""><small>${esc(loc(a,'category'))}</small><h2>${esc(loc(a,'title'))}</h2><p>${esc(loc(a,'subtitle'))}</p><span>${T().read} ${I('arrow',16)}</span></a>`).join('')}</div></main>`)}
const paragraphs=t=>String(t||'').split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
function articlePage(){const a=articleFor(state.id);if(!a)return notFound();const p=state.places.find(x=>x.id===a.place_id);layout(`<main class="article-page"><a class="back" href="#stories">← ${T().nav[3]}</a><header><p class="eyebrow">${esc(loc(a,'category'))}</p><h1>${esc(loc(a,'title'))}</h1><p>${esc(loc(a,'subtitle'))}</p></header><img class="article-cover" src="${esc(imagePath(a.img||p?.img))}" alt=""><article>${paragraphs(loc(a,'body','body_en')||loc(a,'subtitle','subtitle_en'))}</article>${p?`<a class="related-place" href="#place/${p.id}">${I('pin')} ${esc(loc(p,'name','en'))} ${I('arrow')}</a>`:''}</main>`)}
function contribute(){layout(`<main class="contribute-page"><section class="page-intro"><p class="eyebrow">${T().nav[4]}</p><h1>${T().contributeTitle}</h1><p>${T().contributeIntro}</p></section><form id="contribution-form" class="contribution-form"><label>${T().type}<select name="type" required><option value="">—</option><option>${state.lang==='en'?'Place / Shop':'地點／店舖'}</option><option>${state.lang==='en'?'Organization':'機構／團體'}</option><option>${state.lang==='en'?'Activity':'活動'}</option><option>${state.lang==='en'?'Person / Story':'人物／故事'}</option></select></label><label>${T().name}<input name="name" required></label><label>${T().address}<input name="address"></label><label>${T().contact}<input name="contact"></label><label class="wide">${T().reason}<textarea name="description" rows="7" required></textarea></label><button class="button">${T().submit} ${I('arrow')}</button></form></main>`)}
function about(){layout(`<main class="about-page"><div><p class="eyebrow">ABOUT US</p><h1>${T().aboutTitle}</h1><p>${T().aboutBody}</p><a class="button" href="#map">${T().explore} ${I('arrow')}</a></div><img src="assets/macau-waterfront.png" alt="Macau"></main>`)}
function notFound(){layout(`<main class="not-found"><h1>404</h1><a href="#home">${T().nav[0]}</a></main>`)}
function parseHash(){const raw=location.hash.slice(1)||'home';const [path,qs='']=raw.split('?');const [page,id='']=path.split('/');state.page=navKeys.includes(page)||['place','route','article'].includes(page)?page:'home';state.id=decodeURIComponent(id);const p=new URLSearchParams(qs);if(p.get('cat'))state.cat=p.get('cat')}
function render(){if(map){map.remove();map=null}parseHash();({home,map:mapPage,place:placePage,routes:routesPage,route:routePage,stories:storiesPage,article:articlePage,contribute,about}[state.page]||home)();document.documentElement.lang=state.lang==='en'?'en':'zh-Hant';scrollTo(0,0)}
async function fetchJSON(url,fallback){try{const r=await fetch(url);if(!r.ok)throw 0;return await r.json()}catch{return fallback}}
async function init(){const [places,articles,routes,site,config]=await Promise.all([fetchJSON('/api/places',[]),fetchJSON('/api/articles',[]),fetchJSON('/api/routes',[]),fetchJSON('/api/site',fallbackSite),fetchJSON('/api/config',{})]);Object.assign(state,{places,articles,routes,site:{...fallbackSite,...site},config});render()}
addEventListener('hashchange',render);
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),f=e.target.closest('[data-filter]'),v=e.target.closest('[data-view]'),q=e.target.closest('[data-quick]');if(a?.dataset.action==='language'){state.lang=state.lang==='zh'?'en':'zh';localStorage.setItem('gg-lang',state.lang);render()}if(a?.dataset.action==='menu'){state.menu=!state.menu;render()}if(a?.dataset.action==='search'){$('input[name=q]')?.focus()}if(f){state[f.dataset.filter]=f.dataset.value;mapPage()}if(v){state.view=v.dataset.view;mapPage()}if(q){state.query=q.dataset.quick;location.hash='map'}});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-search-form],[data-map-search]')){e.preventDefault();state.query=new FormData(e.target).get('q')||'';location.hash='map';if(state.page==='map')mapPage()}if(e.target.id==='contribution-form'){e.preventDefault();const form=e.target,body=Object.fromEntries(new FormData(form));try{const r=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw new Error(result.error);form.innerHTML=`<div class="form-success"><h2>✓</h2><p>${T().success}</p><a class="button" href="#map">${T().explore}</a></div>`}catch(err){alert(err.message)}}});
init();
